///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.searchList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.searchList = async function () {
    /* sdd-asis-lifecycle:begin fn_searchList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ($c.util.getComponent('cal_startDate').getValue() > $c.util.getComponent('cal_endDate').getValue()) {
        await $c.win.alert('시작일이 종료일보다 이후 일자 입니다.');
        return;
    }
    $c.util.getComponent('ipt_method').setValue("disclsConsultApplList");
    $("form[name='disclsConsultForm']").attr("action", "disclsConsult.do");
    $("form[name='disclsConsultForm']").attr("onsubmit", "");
    await scwin.tx_fn_searchList();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.goWrite
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.goWrite = async function () {
    /* sdd-asis-lifecycle:begin fn_goWrite — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('ipt_method').setValue("disclsConsultAppl");
    $("form[name='disclsConsultForm']").attr("action", "disclsConsult.do");
    { const nr = await scwin.tx_fn_goWrite(); if (nr && nr.responseJSON && nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil11010/jldfil11010.xml", { "method": "disclsConsultAppl" }); } };
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.goView
 * @author Inswave
 * @date 2026. 09. 29
 * @param ipt_disclsConsultApplId disclsConsultProcsStatCd
 * @returns
 * @hidden N
*/
scwin.goView = async function (ipt_disclsConsultApplId, disclsConsultProcsStatCd) {
    /* sdd-asis-lifecycle:begin fn_goView — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (disclsConsultProcsStatCd === '1') {
        $c.util.getComponent('ipt_method').setValue("disclsConsultAppl");
    } else {
        $c.util.getComponent('ipt_method').setValue("disclsConsultApplView");
    }
    $c.util.getComponent('ipt_disclsConsultApplId').setValue(ipt_disclsConsultApplId);
    $("form[name='disclsConsultForm']").attr("action", "disclsConsult.do");
    { const nr = await scwin.tx_fn_goView(); if (nr && nr.responseJSON && nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil11010/jldfil11010.xml", { "method": "disclsConsultAppl", "disclsConsultApplId": ipt_disclsConsultApplId }); } };
    /* sdd-asis-lifecycle:end */
};



/**
 * @event
 * @name scwin.krxpage_pagenavigator_83_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param index
 * @returns
 * @hidden N
*/
scwin.krxpage_pagenavigator_83_onclick = function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_searchListReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_83.page' }); } scwin.tx_fn_searchList(); };
